import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

export class ValidationError extends Error {}

function newId() {
  return randomBytes(4).toString('hex');
}

function cleanText(value, { field, required = false, max = 200 }) {
  const text = typeof value === 'string' ? value.trim() : '';
  if (required && !text) throw new ValidationError(`${field} is required`);
  if (text.length > max) throw new ValidationError(`${field} must be ${max} characters or fewer`);
  return text;
}

export class BookStore {
  #file;
  #books = [];
  #pendingWrite = Promise.resolve();

  constructor(file) {
    this.#file = file;
  }

  async load() {
    try {
      const raw = await readFile(this.#file, 'utf8');
      this.#books = JSON.parse(raw);
    } catch (err) {
      if (err.code !== 'ENOENT') throw err;
      this.#books = [];
    }
    return this;
  }

  all() {
    return [...this.#books];
  }

  reading() {
    return this.#books.filter((b) => !b.finishedAt).sort(byNewest('addedAt'));
  }

  finished() {
    return this.#books.filter((b) => b.finishedAt).sort(byNewest('finishedAt'));
  }

  get(id) {
    return this.#books.find((b) => b.id === id) ?? null;
  }

  async add({ title, author, notes }) {
    const book = {
      id: newId(),
      title: cleanText(title, { field: 'Title', required: true }),
      author: cleanText(author, { field: 'Author', required: true }),
      notes: cleanText(notes, { field: 'Notes', max: 20000 }),
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    this.#books.push(book);
    await this.#save();
    return book;
  }

  async finish(id) {
    const book = this.get(id);
    if (!book) return null;
    if (!book.finishedAt) {
      book.finishedAt = new Date().toISOString();
      await this.#save();
    }
    return book;
  }

  async updateNotes(id, notes) {
    const book = this.get(id);
    if (!book) return null;
    book.notes = cleanText(notes, { field: 'Notes', max: 20000 });
    await this.#save();
    return book;
  }

  // Writes are chained so two quick mutations can't interleave, and go through a
  // temp file + rename so a crash mid-write can't leave a truncated JSON file.
  #save() {
    const snapshot = JSON.stringify(this.#books, null, 2);
    this.#pendingWrite = this.#pendingWrite.then(async () => {
      await mkdir(dirname(this.#file), { recursive: true });
      const tmp = `${this.#file}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, this.#file);
    });
    return this.#pendingWrite;
  }
}

function byNewest(field) {
  return (a, b) => (a[field] < b[field] ? 1 : a[field] > b[field] ? -1 : 0);
}

