const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export function escape(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => ESCAPES[c]);
}

// Tagged template: interpolated values are escaped unless wrapped in raw().
export function html(strings, ...values) {
  let out = strings[0];
  values.forEach((value, i) => {
    out += value instanceof Raw ? value.text : Array.isArray(value)
      ? value.map((v) => (v instanceof Raw ? v.text : escape(v))).join('')
      : escape(value);
    out += strings[i + 1];
  });
  return new Raw(out);
}

class Raw {
  constructor(text) {
    this.text = text;
  }
  toString() {
    return this.text;
  }
}

export function raw(text) {
  return new Raw(text);
}

export function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

export function layout(title, body) {
  return html`<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${title} · Bookshelf</title>
  <style>
    :root { color-scheme: light dark; }
    body { font: 16px/1.5 system-ui, sans-serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; }
    header a { text-decoration: none; color: inherit; font-weight: 700; font-size: 1.25rem; }
    h1 { font-size: 1.5rem; margin: 1.5rem 0 0.5rem; }
    h2 { font-size: 1.1rem; margin: 2rem 0 0.5rem; color: #666; text-transform: uppercase; letter-spacing: 0.05em; }
    ul.books { list-style: none; padding: 0; margin: 0; }
    ul.books li { padding: 0.6rem 0; border-bottom: 1px solid #ddd; display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; }
    ul.books .author, .meta { color: #777; }
    .empty { color: #777; font-style: italic; }
    form.stack { display: grid; gap: 0.75rem; max-width: 30rem; }
    label { display: grid; gap: 0.25rem; font-weight: 600; }
    input, textarea { font: inherit; padding: 0.5rem; border: 1px solid #aaa; border-radius: 4px; width: 100%; box-sizing: border-box; }
    textarea { min-height: 8rem; }
    button { font: inherit; padding: 0.5rem 1rem; border-radius: 4px; border: 1px solid #555; background: #333; color: #fff; cursor: pointer; }
    button.quiet { background: transparent; color: inherit; }
    .error { color: #b00020; }
    .notes { white-space: pre-wrap; }
    .share { margin-top: 2rem; }
    .share input { font-size: 0.9rem; }
    @media (prefers-color-scheme: dark) { ul.books li { border-color: #444; } }
  </style>
</head>
<body>
  <header><a href="/">📚 Bookshelf</a></header>
  <main>${body}</main>
</body>
</html>`.text;
