import { ValidationError } from './store.js';
import { escape, formatDate, html, layout, raw } from './html.js';

const MAX_BODY = 64 * 1024;

export function createApp(store) {
  return async function handle(req, res) {
    try {
      const url = new URL(req.url, 'http://localhost');
      const route = match(req.method, url.pathname);
      if (!route) return notFound(res);
      await route.handler({ req, res, url, params: route.params, store });
    } catch (err) {
      if (err instanceof ValidationError) return send(res, 400, layout('Error', errorPage(err.message)));
      console.error(err);
      send(res, 500, layout('Error', errorPage('Something went wrong.')));
    }
  };
}

const routes = [
  ['GET', /^\/$/, home],
  ['POST', /^\/books$/, createBook],
  ['GET', /^\/books\/([a-z0-9]+)$/, showBook],
  ['POST', /^\/books\/([a-z0-9]+)\/finish$/, finishBook],
  ['POST', /^\/books\/([a-z0-9]+)\/notes$/, updateNotes],
];

function match(method, pathname) {
  for (const [m, pattern, handler] of routes) {
    if (m !== method) continue;
    const found = pathname.match(pattern);
    if (found) return { handler, params: found.slice(1) };
  }
  return null;
}

// --- Handlers ---------------------------------------------------------------

async function home({ res, url, store }) {
  const error = url.searchParams.get('error');
  const body = html`
    <h1>Currently reading</h1>
    ${bookList(store.reading(), 'Nothing on the go. Add a book below.')}

    <h2>Finished</h2>
    ${bookList(store.finished(), 'Nothing finished yet.')}

    <h2>Add a book</h2>
    ${error ? html`<p class="error">${error}</p>` : ''}
    <form class="stack" method="post" action="/books">
      <label>Title <input name="title" required maxlength="200" value="${url.searchParams.get('title') ?? ''}"></label>
      <label>Author <input name="author" required maxlength="200" value="${url.searchParams.get('author') ?? ''}"></label>
      <label>Notes <textarea name="notes" placeholder="Why you picked it up, where you are, what you think…"></textarea></label>
      <button type="submit">Add book</button>
    </form>`;
  send(res, 200, layout('Bookshelf', body));
}

async function createBook({ req, res, store }) {
  const form = await readForm(req);
  try {
    const book = await store.add(form);
    redirect(res, `/books/${book.id}`);
  } catch (err) {
    if (!(err instanceof ValidationError)) throw err;
    const q = new URLSearchParams({ error: err.message, title: form.title ?? '', author: form.author ?? '' });
    redirect(res, `/?${q}`);
  }
}

async function showBook({ req, res, url, params, store }) {
  const book = store.get(params[0]);
  if (!book) return notFound(res);
  const shareUrl = `${req.headers['x-forwarded-proto'] ?? 'http'}://${req.headers.host ?? 'localhost'}${url.pathname}`;
  const body = html`
    <h1>${book.title}</h1>
    <p class="meta">by ${book.author}</p>
    <p class="meta">
      ${book.finishedAt
        ? html`Finished ${formatDate(book.finishedAt)} · started ${formatDate(book.addedAt)}`
        : html`Reading since ${formatDate(book.addedAt)}`}
    </p>
    ${book.finishedAt ? '' : html`
      <form method="post" action="/books/${book.id}/finish">
        <button type="submit">Mark as finished</button>
      </form>`}

    <h2>Notes</h2>
    <form class="stack" method="post" action="/books/${book.id}/notes">
      <textarea name="notes" aria-label="Notes">${book.notes}</textarea>
      <div><button type="submit" class="quiet">Save notes</button></div>
    </form>

    <div class="share">
      <label>Share link <input readonly value="${shareUrl}" onclick="this.select()"></label>
    </div>
    <p><a href="/">← All books</a></p>`;
  send(res, 200, layout(book.title, body));
}

async function finishBook({ res, params, store }) {
  const book = await store.finish(params[0]);
  if (!book) return notFound(res);
  redirect(res, `/books/${book.id}`);
}

async function updateNotes({ req, res, params, store }) {
  const form = await readForm(req);
  const book = await store.updateNotes(params[0], form.notes);
  if (!book) return notFound(res);
  redirect(res, `/books/${book.id}`);
}

// --- Fragments & helpers ----------------------------------------------------

function bookList(books, emptyMessage) {
  if (books.length === 0) return html`<p class="empty">${emptyMessage}</p>`;
  return html`<ul class="books">${books.map(
    (b) => html`<li><a href="/books/${b.id}">${b.title}</a><span class="author">${b.author}</span></li>`,
  )}</ul>`;
}

function errorPage(message) {
  return html`<h1>Error</h1><p class="error">${message}</p><p><a href="/">← All books</a></p>`;
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.setEncoding('utf8');
    req.on('data', (chunk) => {
      body += chunk;
      if (body.length > MAX_BODY) {
        reject(new ValidationError('Form is too large'));
        req.destroy();
      }
    });
    req.on('end', () => resolve(Object.fromEntries(new URLSearchParams(body))));
    req.on('error', reject);
  });
}

function send(res, status, body) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

function notFound(res) {
  send(res, 404, layout('Not found', errorPage("That book isn't on the shelf.")));
}

export { escape, raw };

