import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { BookStore, ValidationError } from '../src/store.js';

let dir;
let file;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'bookshelf-'));
  file = join(dir, 'nested', 'books.json');
});

afterEach(() => rm(dir, { recursive: true, force: true }));

describe('BookStore', () => {
  it('starts empty when the file does not exist', async () => {
    const store = await new BookStore(file).load();
    expect(store.all()).toEqual([]);
  });

  it('adds a book as currently reading and persists it as JSON', async () => {
    const store = await new BookStore(file).load();
    const book = await store.add({ title: '  Dune ', author: 'Frank Herbert', notes: 'Spice.' });

    expect(book).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.', finishedAt: null });
    expect(book.id).toMatch(/^[a-f0-9]{8}$/);
    expect(store.reading()).toEqual([book]);
    expect(store.finished()).toEqual([]);

    const onDisk = JSON.parse(await readFile(file, 'utf8'));
    expect(onDisk).toEqual([book]);
  });

  it('survives a restart', async () => {
    const first = await new BookStore(file).load();
    const book = await first.add({ title: 'Dune', author: 'Frank Herbert' });
    await first.finish(book.id);

    const second = await new BookStore(file).load();
    expect(second.get(book.id)).toEqual(first.get(book.id));
    expect(second.finished()).toHaveLength(1);
  });

  it('moves a book to finished and keeps the first finish date', async () => {
    const store = await new BookStore(file).load();
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' });

    const finished = await store.finish(book.id);
    expect(finished.finishedAt).toBeTruthy();
    expect(store.reading()).toEqual([]);
    expect(store.finished()).toEqual([finished]);

    const again = await store.finish(book.id);
    expect(again.finishedAt).toBe(finished.finishedAt);
  });

  it('returns null for unknown ids', async () => {
    const store = await new BookStore(file).load();
    expect(store.get('nope')).toBeNull();
    expect(await store.finish('nope')).toBeNull();
    expect(await store.updateNotes('nope', 'x')).toBeNull();
  });

  it('updates notes', async () => {
    const store = await new BookStore(file).load();
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' });
    await store.updateNotes(book.id, 'Finished part one.');
    expect(store.get(book.id).notes).toBe('Finished part one.');
  });

  it('rejects books without a title or author', async () => {
    const store = await new BookStore(file).load();
    await expect(store.add({ title: '', author: 'X' })).rejects.toThrow(ValidationError);
    await expect(store.add({ title: 'X', author: '   ' })).rejects.toThrow(/Author is required/);
    expect(store.all()).toEqual([]);
  });

  it('lists newest first', async () => {
    const store = await new BookStore(file).load();
    const a = await store.add({ title: 'A', author: 'X' });
    await new Promise((r) => setTimeout(r, 5));
    const b = await store.add({ title: 'B', author: 'X' });
    expect(store.reading().map((x) => x.id)).toEqual([b.id, a.id]);
  });

  it('does not corrupt the file under concurrent writes', async () => {
    const store = await new BookStore(file).load();
    await Promise.all(Array.from({ length: 20 }, (_, i) => store.add({ title: `Book ${i}`, author: 'X' })));
    const onDisk = JSON.parse(await readFile(file, 'utf8'));
    expect(onDisk).toHaveLength(20);
  });
});

