import { mkdtemp, rm } from 'node:fs/promises';
import { createServer } from 'node:http';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app.js';
import { BookStore } from '../src/store.js';

let dir;
let server;
let base;
let store;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'bookshelf-'));
  store = await new BookStore(join(dir, 'books.json')).load();
  server = createServer(createApp(store));
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(async () => {
  await new Promise((r) => server.close(r));
  await rm(dir, { recursive: true, force: true });
});

const get = (path) => fetch(base + path, { redirect: 'manual' });
const post = (path, fields = {}) =>
  fetch(base + path, {
    method: 'POST',
    redirect: 'manual',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields).toString(),
  });

describe('home page', () => {
  it('shows empty states and the add form', async () => {
    const res = await get('/');
    const text = await res.text();
    expect(res.status).toBe(200);
    expect(text).toContain('Currently reading');
    expect(text).toContain('Nothing on the go');
    expect(text).toContain('Nothing finished yet');
    expect(text).toContain('<form class="stack" method="post" action="/books">');
  });

  it('separates books that are being read from finished ones', async () => {
    const reading = await store.add({ title: 'Dune', author: 'Frank Herbert' });
    const done = await store.add({ title: 'Emma', author: 'Jane Austen' });
    await store.finish(done.id);

    const text = await (await get('/')).text();
    const readingSection = text.slice(text.indexOf('Currently reading'), text.indexOf('Finished'));
    const finishedSection = text.slice(text.indexOf('Finished'), text.indexOf('Add a book'));
    expect(readingSection).toContain(`href="/books/${reading.id}"`);
    expect(readingSection).not.toContain('Emma');
    expect(finishedSection).toContain(`href="/books/${done.id}"`);
    expect(finishedSection).not.toContain('Dune');
  });
});

